package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class AddSubChainsTest {
 @Test public void everyGradeOnePathAndBlankHelp(){Set<String> seen=new HashSet<>();Set<String> ops=new HashSet<>();for(int i=0;i<AddSubChains.count(10);i++){Question q=AddSubChains.at(10,i);assertTrue(seen.add(q.signature()));int[] v=AddSubChains.read(q);assertNotNull(v);int middle=v[0];for(int n=0;n<v[1];n++)middle+=v[3];int answer=middle;for(int n=0;n<v[2];n++)answer+=v[4];assertTrue(middle>=0&&middle<=10&&answer>=0&&answer<=10);ops.add(v[3]+","+v[4]);q.answers=new String[]{"poison"};q.expression="poison";Checker c=new Checker();assertTrue(c.check(q,List.of(),List.of(""+answer)).correct());assertEquals(Checker.Status.WRONG_ANSWER,c.check(q,List.of(),List.of(""+(answer+1))).status);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(2,h.size());assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));assertTrue(h.step(0).accepts(""+middle));assertTrue(h.step(1).accepts(""+answer));for(int k=0;k<2;k++)assertFalse(h.step(k).before.matches(".*[0-9].*"));}assertEquals(1331,seen.size());assertEquals(4,ops.size());}
 @Test public void threeGradeBoundsAndFreshRealSupply(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();for(int grade=1;grade<=3;grade++){assertTrue(pack.inGrade(AddSubChains.ID,grade));int max=grade==1?10:grade==2?100:500;CurriculumLimits limits=GlobalCurriculum.limits(pack.id,AddSubChains.ID,grade);assertEquals(max,AddSubChains.maximum(limits));Generator g=new Generator(new Random(202));List<String> recent=new ArrayList<>();for(int i=0;i<150;i++){Question q=g.next(AddSubChains.ID,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=AddSubChains.read(q);assertNotNull(v);for(int j:new int[]{0,1,2,5,6})assertTrue(v[j]>=0&&v[j]<=max);}for(int index:new int[]{0,AddSubChains.count(max)-1})assertNotNull(AddSubChains.read(AddSubChains.at(max,index)));}assertFalse(pack.inGrade(AddSubChains.ID,4));assertFalse(Curriculum.inCurriculum(Catalog.get(AddSubChains.ID),2022));Question q=AddSubChains.make(1,1,true,1,false);q.prompt="1 − 2 + 1 = □";assertNull(AddSubChains.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("0")).status);}
}
